
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_op_g96_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_op_g96", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.864883705527294e-02, -5.835597770787880e-02, -5.792541969184807e-02, -5.728649627671791e-02, -5.632594641981695e-02, -5.485604143529330e-02, -5.255502188585370e-02, -4.886399422189356e-02, -4.289182354151000e-02, -3.396545145415310e-02, -2.537105465877814e-02, -2.963060630724406e-02, -3.501831961155927e-02, -2.801257355065587e-02, -1.740761263710967e-02, -6.260823747820104e-03, -6.620034974070251e-04, -7.926615530804452e-06, -4.583364926705971e-09, -6.825507626985915e-14]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


